+/** Picks a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  const supported = new Set(LANGUAGES);
+  const candidates = [];
+  for (const part of raw.split(",")) {
+    const [rawTag, ...params] = part.split(";").map((s) => s.trim());
+    if (!rawTag) continue;
+    const tag = rawTag.toLowerCase();
+    if (!/^[a-z]+(?:-[a-z0-9]+)*$/.test(tag)) continue;
+    const primary = tag.split("-")[0];
+    if (!supported.has(primary)) continue;
+    let q = 1;
+    let valid = true;
+    for (const param of params) {
+      if (!param) continue;
+      const m = /^q\s*=\s*(.+)$/i.exec(param);
+      if (!m) continue;
+      const val = m[1].trim();
+      if (!/^(?:0(?:\.\d+)?|1(?:\.0+)?)$/.test(val)) {
+        valid = false;
+        break;
+      }
+      q = Number(val);
+    }
+    if (!valid || !(q > 0)) continue;
+    candidates.push({ lang: primary, q, index: candidates.length });
+  }
+  candidates.sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0]?.lang ?? fallback;
+}
